begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('f1800000-0000-4000-8000-000000000001','photo-owner@mizyun.test'),('f1800000-0000-4000-8000-000000000002','photo-other@mizyun.test');
insert into public.food_entries(id,user_id,name,consumed_at) values('f1800000-0000-4000-8000-000000000003','f1800000-0000-4000-8000-000000000001','Synthetic meal',now()),('f1800000-0000-4000-8000-000000000004','f1800000-0000-4000-8000-000000000002','Other synthetic meal',now());
create temp table photo_state(value jsonb);grant all on photo_state to authenticated,service_role;
set local role authenticated;set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='f1800000-0000-4000-8000-000000000001';
select throws_ok($$select public.meal_photo('begin','{"mealId":"f1800000-0000-4000-8000-000000000003","operationId":"f1800000-0000-4000-8000-000000000005","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","width":640,"height":320,"byteSize":1024}')$$,'P0001','meal_photo_not_found','Direct authenticated mutation cannot bypass disabled API/sanitizer');
select throws_ok($$insert into public.meal_photos(id,user_id,food_entry_id,operation_id,digest,state,width,height) values('f1800000-0000-4000-8000-000000000006','f1800000-0000-4000-8000-000000000001','f1800000-0000-4000-8000-000000000003','f1800000-0000-4000-8000-000000000005',repeat('a',64),'ready',640,320)$$,'42501',null,'Owner cannot fabricate trusted association');
reset role;set local request.jwt.claim.role='service_role';
insert into photo_state select public.meal_photo('begin','{"mealId":"f1800000-0000-4000-8000-000000000003","operationId":"f1800000-0000-4000-8000-000000000005","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","width":640,"height":320,"byteSize":1024}','f1800000-0000-4000-8000-000000000001');
select is(public.meal_photo('begin','{"mealId":"f1800000-0000-4000-8000-000000000003","operationId":"f1800000-0000-4000-8000-000000000005","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","width":640,"height":320,"byteSize":1024}','f1800000-0000-4000-8000-000000000001')->>'assetId',(select value->>'assetId' from photo_state),'Lost begin response reuses one registered media asset');
select throws_ok($$select public.meal_photo('begin','{"mealId":"f1800000-0000-4000-8000-000000000003","operationId":"f1800000-0000-4000-8000-000000000005","digest":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","width":640,"height":320,"byteSize":1024}','f1800000-0000-4000-8000-000000000001')$$,'P0001','meal_photo_conflict','Retry cannot replace bytes');
select throws_ok($$select public.meal_photo('begin','{"mealId":"f1800000-0000-4000-8000-000000000004","operationId":"f1800000-0000-4000-8000-000000000005","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","width":640,"height":320,"byteSize":1024}','f1800000-0000-4000-8000-000000000001')$$,'P0001','meal_photo_not_found','Captured owner cannot attach to another account meal');
set local request.jwt.claim.role='authenticated';set local role authenticated;
select throws_ok($$insert into storage.objects(bucket_id,name) select 'private-media',value->>'objectPath' from photo_state$$,'P0001','meal_photo_conflict','Owner cannot upload unsanitized bytes directly');
reset role;set local request.jwt.claim.role='service_role';
insert into storage.objects(bucket_id,name) select 'private-media',value->>'objectPath' from photo_state;
select lives_ok($$select public.meal_photo('commit',jsonb_build_object('mealId','f1800000-0000-4000-8000-000000000003','assetId',(select value->>'assetId' from photo_state)),'f1800000-0000-4000-8000-000000000001')$$,'Server commit associates only registered private photo');
select lives_ok($$select public.meal_photo('commit',jsonb_build_object('mealId','f1800000-0000-4000-8000-000000000003','assetId',(select value->>'assetId' from photo_state)),'f1800000-0000-4000-8000-000000000001')$$,'Lost commit response is idempotent');
set local role authenticated;set local request.jwt.claim.role='authenticated';
select is((select photo_asset_id::text from public.food_entries where id='f1800000-0000-4000-8000-000000000003'),(select value->>'assetId' from photo_state),'Owner reads typed photo association');
select is((select count(*) from storage.objects where name=(select value->>'objectPath' from photo_state)),1::bigint,'Ready bytes are privately visible to owner');
select throws_ok($$update storage.objects set name='f1800000-0000-4000-8000-000000000001/escaped.jpg' where name=(select value->>'objectPath' from photo_state)$$,'P0001','meal_photo_conflict','Retained object cannot escape canonical cleanup namespace');
select throws_ok($$update public.media_assets set object_path='f1800000-0000-4000-8000-000000000001/escaped.jpg' where id=(select (value->>'assetId')::uuid from photo_state)$$,'P0001','meal_photo_conflict','Owner cannot alter trusted storage coordinates');
set local request.jwt.claim.sub='f1800000-0000-4000-8000-000000000002';
select is((select count(*) from public.meal_photos),0::bigint,'Cross-account association denied by RLS');
select is((select count(*) from storage.objects where name=(select value->>'objectPath' from photo_state)),0::bigint,'Cross-account direct bytes denied by RLS');
select throws_ok($$select public.meal_photo('get','{"mealId":"f1800000-0000-4000-8000-000000000003"}')$$,'P0001','meal_photo_not_found','Cross-account signing lookup denied');
reset role;set local request.jwt.claim.role='service_role';
select lives_ok($$delete from public.food_entries where id='f1800000-0000-4000-8000-000000000003'$$,'Meal deletion revokes and durably queues retained bytes');
select is((select count(*) from public.meal_photo_cleanup_jobs where object_path=(select value->>'objectPath' from photo_state)),1::bigint,'Cleanup authority persists after meal disappearance');
select throws_ok($$insert into storage.objects(bucket_id,name) select 'private-media',value->>'objectPath' from photo_state$$,'P0001','meal_photo_conflict','Late upload cannot resurrect deleted meal photo');
set local role authenticated;set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='f1800000-0000-4000-8000-000000000001';
select is((select count(*) from storage.objects where name=(select value->>'objectPath' from photo_state)),0::bigint,'Deleted photo immediately loses authenticated byte access');
reset role;set local request.jwt.claim.role='service_role';
delete from photo_state;
insert into public.food_entries(id,user_id,name,consumed_at) values('f1800000-0000-4000-8000-000000000007','f1800000-0000-4000-8000-000000000001','Active account cascade fixture',now());
insert into photo_state select public.meal_photo('begin','{"mealId":"f1800000-0000-4000-8000-000000000007","operationId":"f1800000-0000-4000-8000-000000000008","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","width":640,"height":320,"byteSize":1024}','f1800000-0000-4000-8000-000000000001');
insert into storage.objects(bucket_id,name) select 'private-media',value->>'objectPath' from photo_state where value->>'state'='uploading';
select lives_ok($$select public.meal_photo('commit',jsonb_build_object('mealId','f1800000-0000-4000-8000-000000000007','assetId',(select value->>'assetId' from photo_state where value->>'state'='uploading')),'f1800000-0000-4000-8000-000000000001')$$,'Active ready photo exists before account cascade');
delete from auth.users where id='f1800000-0000-4000-8000-000000000001';
select is((select count(*) from public.meal_photo_cleanup_jobs where user_id='f1800000-0000-4000-8000-000000000001'),2::bigint,'Account cascade preserves both revoked and active photo cleanup jobs');
insert into photo_state select public.meal_photo('begin','{"mealId":"f1800000-0000-4000-8000-000000000004","operationId":"f1800000-0000-4000-8000-000000000009","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","width":640,"height":320,"byteSize":1024}','f1800000-0000-4000-8000-000000000002');
update public.meal_photos set created_at=now()-interval '2 hours' where user_id='f1800000-0000-4000-8000-000000000002';
select lives_ok($$select public.meal_photo_cleanup_pending()$$,'Restart-safe worker revokes abandoned expired upload');
select is((select count(*) from public.meal_photo_cleanup_jobs where user_id='f1800000-0000-4000-8000-000000000002'),1::bigint,'Expired upload keeps durable cleanup authority');
select * from finish();rollback;
